    if (!filePath || !filesByPath[filePath]) throw new Error('Agent 2 returned a change for a file not supplied: ' + filePath);
    if (!recommendation.files.includes(filePath)) throw new Error(filePath + ': Agent 2 used a file not mapped to recommendation ' + recommendationIndex + '.');
    if (!machineTypePattern.test(finalTargetMachineType)) throw new Error(filePath + ': Agent 2 returned invalid targetMachineType ' + finalTargetMachineType + '.');
    if (!extractionKeys.has(filePath + '\u0000' + originalExtractedCode)) throw new Error(filePath + ': Agent 2 originalExtractedCode does not match any Agent 1 extraction.');
    if (!updatedExtractedCode || updatedExtractedCode === originalExtractedCode) throw new Error(filePath + ': Agent 2 marked changeRequired but did not change updatedExtractedCode.');
    const matchingExtraction = extractions.find(extraction => extraction.filePath === filePath && extraction.extractedCode === originalExtractedCode) ?? {};
    const expectedOldType = change.currentMachineType ?? change.oldMachineType ?? matchingExtraction.currentMachineType ?? recommendation.currentMachineType;
    const oldMachineType = validateOnlyMachineTypeChanged(originalExtractedCode, updatedExtractedCode, expectedOldType, finalTargetMachineType, filePath);
    const occurrences = filesByPath[filePath].modifiedContent.split(originalExtractedCode).length - 1;
    if (occurrences !== 1) throw new Error(filePath + ': originalExtractedCode must occur exactly once, found ' + occurrences + '.');
    filesByPath[filePath].modifiedContent = filesByPath[filePath].modifiedContent.replace(originalExtractedCode, updatedExtractedCode);
    const appliedChange = { ...change, recommendationIndex, instanceName: recommendation.instanceName, projectName: recommendation.projectName, originalExtractedCode, updatedExtractedCode, oldMachineType, targetMachineType: finalTargetMachineType, filePath };
    filesByPath[filePath].appliedChanges.push(appliedChange);
    instance.appliedChanges.push(appliedChange);
    instance.changedFiles.push(filePath);
  }
  const instanceResults = finalizeInstances(instanceMap);
  const updateFiles = Object.values(filesByPath).filter(file => file.appliedChanges.length);
  const updatedFiles = updateFiles.map(file => ({ filePath: file.filePath, changeCount: file.appliedChanges.length, instances: [...new Set(file.appliedChanges.map(change => change.instanceName))] }));
  const pullRequestPayload = {
    title: source.pullRequestTitle ?? 'Apply AI-reviewed GCP VM resize recommendations',
    head: source.branch,
    base: source.baseBranch ?? 'main',
    body: buildPullRequestBody(source, instanceResults, updatedFiles)
  };
  if (!updateFiles.length) {
    output.push({ json: { ...source, shouldUpdateGitHub: false, status: 'not_updated', changes: skippedChanges, instanceResults, updatedFiles: [], review, modifiedContent: null, updatePayload: null, pullRequestPayload: null } });
    continue;
  }
  updateFiles.forEach((file, updateIndex) => {
    output.push({
      json: {
        ...source,
        shouldUpdateGitHub: true,
        status: 'ready_to_update',
        filePath: file.filePath,
        githubSha: file.githubSha,
        githubHtmlUrl: file.githubHtmlUrl,
        changes: file.appliedChanges,
        skippedChanges,
        instanceResults,
        updatedFiles,
        batchUpdateIndex: updateIndex,
        batchUpdateFileCount: updateFiles.length,
        review,
        modifiedContent: file.modifiedContent,
        pullRequestPayload,
        updatePayload: {
          message: source.commitMessage + ' (' + file.appliedChanges.length + ' resize change' + (file.appliedChanges.length === 1 ? '' : 's') + ' in ' + file.filePath + ')',
          content: Buffer.from(file.modifiedContent, 'utf8').toString('base64'),
          sha: file.githubSha,
          branch: source.branch
        }
      }
    });
  });
}
return output;
